    case 1:
      if (lookahead == '\t') ADVANCE(76);
      if (lookahead == ' ') ADVANCE(76);
      END_STATE();
    case 2:
      if (lookahead == '\t') ADVANCE(76);
      if (lookahead == ' ') ADVANCE(76);
      if (lookahead == '#') ADVANCE(1);
